دالة ضغط_التكرار(نص) {
    متغير ن = نص
    متغير ناتج = ""
    متغير حرف = ""
    متغير تكرار = ٠
    من_أجل (ي من ٠ إلى طول(ن) - ١) {
        حرف = ن[ي]
        إذا (ي == طول(ن) - ١ || حرف != ن[ي + ١]) {
            ناتج = ناتج + حرف + تكرار + ١
            تكرار = ٠
        } وإلا {
            تكرار = تكرار + ١
        }
    }
    ارجع ناتج
}
```

